from copy import deepcopy
from enum import Enum
from math import isfinite


class MatrixKind(Enum):
    DENSE = "dense"


class MatrixCatalog:
    def __init__(self, kind, vectors, classes, selected=None):
        if kind is not MatrixKind.DENSE:
            raise ValueError("unsupported kind")
        if not isinstance(vectors, list) or not isinstance(classes, list) or len(vectors) != len(classes):
            raise ValueError("invalid dataset")
        width = 0
        for index, vector in enumerate(vectors):
            if not isinstance(vector, list) or not vector:
                raise ValueError("invalid vector")
            if index == 0:
                width = len(vector)
            if len(vector) != width or any(
                not isinstance(value, (int, float))
                or isinstance(value, bool)
                or not isfinite(value)
                for value in vector
            ):
                raise ValueError("invalid vector")
        try:
            for label in classes:
                hash(label)
        except TypeError as exc:
            raise ValueError("invalid class") from exc
        if selected is not None:
            if not isinstance(selected, list):
                raise ValueError("invalid selection")
            try:
                selected_set = set(selected)
            except TypeError as exc:
                raise ValueError("invalid selection") from exc
            if len(selected_set) != len(selected):
                raise ValueError("invalid selection")
        else:
            selected_set = None
        retained = [
            index for index, label in enumerate(classes)
            if selected_set is None or label in selected_set
        ]
        self.vectors = [vectors[index] for index in retained]
        self.classes = deepcopy([classes[index] for index in retained])
        self._width = width

    @property
    def width(self):
        return self._width

